import { Group, Mesh, PlaneGeometry, Vector3, Euler } from 'three/webgpu';
import { MeshBasicNodeMaterial } from 'three/tsl';
import { gsap } from 'gsap';
import primitives from '@/primitives';
import { createSMDFTextMesh } from '@/text';

/**
 * @typedef {Object} NodeConfig
 * @property {{x:number,y:number,z:number}} position
 * @property {{x:number,y:number,z:number}} rotation
 * @property {{x:number,y:number,z:number}} scale
 * @property {{imageUrl:string}} assets
 * @property {{textContent:string}} textContent
 * @property {{palette:Object}} colors
 * @property {Array<{name:string,params:any}>} cinematicPrimitives
 * @property {Object} atlasRegion
 */

/**
 * @typedef {Object} NodeContext
 * @property {{load: (url:string)=>import('three').Texture}} textureLoader
 * @property {{fontAtlas:any}} fontAtlas
 * @property {{primitives:Record<string,Function>}} primitives
 */

/**
 * Creates the Journal card 1 label node.
 * @param {NodeConfig} config
 * @param {NodeContext} ctx
 * @returns {import('three').Object3D}
 */
export default function createNode(config, ctx) {
  // root container
  const root = new Group();

  // ---------- Textured Plane ----------
  const tex = ctx.textureLoader.load(config.assets.imageUrl);
  const planeMat = new MeshBasicNodeMaterial({ map: tex });
  // simple 1×1 unit plane; scale will be applied via config.scale
  const planeGeo = new PlaneGeometry(1, 1);
  const planeMesh = new Mesh(planeGeo, planeMat);
  planeMesh.position.set(
    config.position?.x ?? 0,
    config.position?.y ?? 0,
    config.position?.z ?? 0
  );
  planeMesh.rotation.set(
    config.rotation?.x ?? 0,
    config.rotation?.y ?? 0,
    config.rotation?.z ?? 0
  );
  planeMesh.scale.set(
    config.scale?.x ?? 1,
    config.scale?.y ?? 1,
    config.scale?.z ?? 1
  );

  root.add(planeMesh);

  // ---------- MSDF Text ----------
  // The atlas region information is used by the text utility.
  const textMesh = createSMDFTextMesh({
    fontAtlas: ctx.fontAtlas,
    text: config.textContent?.textContent ?? '',
    size: 0.13, // using the body scale from design tokens as a reasonable default
    color: config.colors?.ink ?? '#16161d',
    atlas: config.atlasRegion?.atlas ?? 0,
    region: {
      x: config.atlasRegion?.sourceRect?.[0] ?? 0,
      y: config.atlasRegion?.sourceRect?.[1] ?? 0,
      width: config.atlasRegion?.sourceRect?.[2] ?? 512,
      height: config.atlasRegion?.sourceRect?.[3] ?? 320,
    },
  });

  // Position the text slightly in front of the plane to avoid z‑fighting
  textMesh.position.set(
    (config.position?.x ?? 0),
    (config.position?.y ?? 0),
    (config.position?.z ?? 0) + 0.001
  );
  textMesh.rotation.copy(planeMesh.rotation);
  textMesh.scale.set(1, 1, 1);

  root.add(textMesh);

  // ---------- Cinematic Primitives ----------
  if (Array.isArray(config.cinematicPrimitives)) {
    for (const primitive of config.cinematicPrimitives) {
      const fn = ctx.primitives[primitive.name];
      if (typeof fn === 'function') {
        fn(root, primitive.params);
      }
    }
  }

  // ---------- Event Handlers ----------
  root.userData.handlers = {};

  // ---------- Cleanup ----------
  const timelines = []; // collect any GSAP timelines we might create later
  root.userData.cleanup = () => {
    // dispose geometries & materials
    planeGeo.dispose();
    planeMat.dispose();
    tex.dispose();

    if (textMesh.geometry) textMesh.geometry.dispose();
    if (textMesh.material) textMesh.material.dispose();

    // kill GSAP timelines
    timelines.forEach((tl) => tl.kill());
  };

  return root;
}
